/**
 * Salesforce Commerce Cloud (SCAPI) Category → canonical Collection.
 *
 * SCAPI uses "categories" (product taxonomy nodes) as the closest analogue to
 * the canonical `Collection` concept.  Categories are hierarchical: each has an
 * optional `parentCategoryId`.  The canonical `type` is always `'MANUAL'` since
 * SCAPI categories are curated by merchandisers rather than auto-generated by
 * query rules.
 *
 * Reference:
 *   GET /product/shopper-products/v1/organizations/{organizationId}/categories
 *   GET /product/shopper-products/v1/organizations/{organizationId}/categories/{categoryId}
 */

import type { Collection, CollectionType } from '../../../schema/collection'
import type { Image } from '../../../schema/shared'
import { toIsoDatetime } from '@opensteward/shared'

// ── Raw SCAPI shapes ──────────────────────────────────────────────────────────

export interface RawScapiCategory {
  id: string
  name?: string
  description?: string
  parentCategoryId?: string
  image?: string | null // URL to thumbnail
  thumbnail?: string | null
  online?: boolean
  createdAt?: string
  lastModified?: string
  [key: string]: unknown
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function mapImage(imageUrl: string | null | undefined): Image | undefined {
  if (!imageUrl) return undefined
  return { url: imageUrl }
}

// ── Transform ─────────────────────────────────────────────────────────────────

export function transformCollection(
  raw: RawScapiCategory,
  type: CollectionType = 'MANUAL',
): Collection {
  return {
    id: raw.id,
    title: raw.name ?? raw.id,
    handle: raw.id,
    description: raw.description ?? undefined,
    type,
    image: mapImage(raw.image ?? raw.thumbnail),
    updatedAt: toIsoDatetime(raw.lastModified),
    metadata: raw as unknown as Record<string, unknown>,
  }
}

/** Canonical Collection → SCAPI category body. */
export function untransformCollection(collection: Partial<Collection>): Record<string, unknown> {
  return {
    id: collection.handle ?? collection.id,
    name: collection.title,
    description: collection.description,
    online: collection.publishedAt ? true : undefined,
    image: collection.image?.url ?? undefined,
  }
}
